// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);

        c.setL1BlockValues(
            1,
            2,
            3,
            bytes32(uint256(42)),
            4,
            bytes32(uint256(5)),
            6,
            7
        );

        assertTrue(c.hash() == bytes32(uint256(42)), "hash should equal the set value");
    }
}
